package gen

import (
	"fmt"
	"go/format"
	"sort"
	"strconv"
	"strings"

	"github.com/khoale-2804/pgb/ir"
)

// pgbVersion is stamped into the versions header of every generated file.
// No timestamps — output is byte-deterministic for the same IR + options.
const pgbVersion = "v0.1.0"

// PassModels emits models.gen.go (pass A): one struct per table (views
// included — they are read-only but share the shape), plus enum types and
// consts. pgb:skip tables emit nothing. The result is gofmt-canonical
// (go/format.Source); unformattable output is an error, never a warning.
func PassModels(sch ir.Schema, opts Options, dir DirectiveSet) ([]byte, error) {
	if opts.Enums == nil {
		opts.Enums = EnumTypes(sch)
	}

	imports := map[string]string{} // import path -> qualifier
	addImports := func(paths []string) {
		for _, p := range paths {
			imports[p] = importQualifier(p)
		}
	}

	var body strings.Builder

	// Enums first: struct fields reference the generated string types.
	for _, e := range sch.Enums {
		enumName := pascalIdent(e.Name)
		body.WriteString("type " + enumName + " string\n\n")
		body.WriteString("const (\n")
		for _, v := range e.Values {
			body.WriteString("\t" + enumName + pascalIdent(v) + " " + enumName + " = " + strconv.Quote(v) + "\n")
		}
		body.WriteString(")\n\n")
	}

	// One struct per table, proto order. The catalog proto carries the
	// system catalogs; stock sqlc-gen-go skips them, and so does the models
	// pass (the builders/statics passes apply the same rule).
	for _, t := range sch.Tables {
		if t.Skip || dir.Table(t.Schema, t.Name).Skip ||
			t.Schema == "pg_catalog" || t.Schema == "information_schema" {
			continue
		}
		structName := singularize(pascalIdent(t.Name))
		if t.Schema != "" && t.Schema != sch.DefaultSchema {
			// Same-name tables across schemas must not collide in one
			// package: prefix the schema ("app.users" -> AppUser), matching
			// the builders/statics naming.
			structName = pascalIdent(t.Schema) + structName
		}

		seen := map[string]int{}
		type field struct {
			name, typ, tag string
		}
		var fields []field
		for _, c := range t.Columns {
			base := pascalIdent(c.Name)
			name := base
			if n := seen[strings.ToLower(base)]; n > 0 {
				name = base + strconv.Itoa(n+1) // case-insensitive collision dedupe
			}
			seen[strings.ToLower(base)]++

			var typ string
			var imp []string
			if d := dir.Column(t.Schema, t.Name, c.Name); d.TypeOverride != "" {
				typ, imp = applyOverride(parseGoType(d.TypeOverride))
			} else {
				typ, imp = GoType(c, opts)
			}
			addImports(imp)
			fields = append(fields, field{name: name, typ: typ, tag: fmt.Sprintf(" `json:%q`", c.Name)})
		}

		if len(fields) == 0 {
			continue
		}
		body.WriteString("type " + structName + " struct {\n")
		for _, f := range fields {
			body.WriteString("\t" + f.name + " " + f.typ + f.tag + "\n")
		}
		body.WriteString("}\n\n")
	}

	out := strings.Builder{}
	out.WriteString("// Code generated by pgb. DO NOT EDIT.\n")
	out.WriteString("// versions:\n")
	out.WriteString("//   pgb " + pgbVersion + "\n")
	if opts.SqlcVersion != "" {
		out.WriteString("//   sqlc " + opts.SqlcVersion + "\n")
	}
	out.WriteString("\npackage " + opts.Package + "\n")
	if len(imports) > 0 {
		paths := make([]string, 0, len(imports))
		for p := range imports {
			paths = append(paths, p)
		}
		sort.Strings(paths)
		out.WriteString("\nimport (\n")
		for _, p := range paths {
			out.WriteString("\t" + strconv.Quote(p) + "\n")
		}
		out.WriteString(")\n")
	}
	out.WriteString(body.String())

	src, err := format.Source([]byte(out.String()))
	if err != nil {
		return nil, fmt.Errorf("pgb: emitted models.gen.go is not valid Go: %w", err)
	}
	return src, nil
}

// initialisms are capitalized as a whole word ("id" -> "ID").
var initialisms = map[string]bool{
	"acl": true, "api": true, "ascii": true, "cidr": true, "cpu": true,
	"css": true, "db": true, "dns": true, "eof": true, "guid": true,
	"html": true, "http": true, "https": true, "id": true, "ip": true,
	"json": true, "pg": true, "qps": true, "ram": true, "rpc": true,
	"sdk": true, "sql": true, "ssh": true, "tcp": true, "tls": true,
	"ttl": true, "udp": true, "ui": true, "uid": true, "uri": true,
	"url": true, "utf8": true, "uuid": true, "vm": true, "xml": true,
}

// pascalIdent converts a Postgres identifier ("last_login_at",
// "user_status", "in-progress") to an exported Go identifier
// ("LastLoginAt", "UserStatus", "InProgress").
func pascalIdent(s string) string {
	var b strings.Builder
	for _, part := range splitIdent(s) {
		upper := strings.ToUpper(part)
		if initialisms[strings.ToLower(part)] {
			b.WriteString(upper)
			continue
		}
		if part == "" {
			continue
		}
		r := []rune(part)
		if r[0] >= '0' && r[0] <= '9' {
			b.WriteString("V" + upper)
			continue
		}
		b.WriteString(string([]rune{toUpperRune(r[0])}) + string(r[1:]))
	}
	if b.Len() == 0 {
		return "X"
	}
	return b.String()
}

func toUpperRune(r rune) rune {
	if r >= 'a' && r <= 'z' {
		return r - 'a' + 'A'
	}
	return r
}

// splitIdent splits on runs of non-alphanumeric characters.
func splitIdent(s string) []string {
	parts := strings.FieldsFunc(s, func(r rune) bool {
		return !(r >= 'a' && r <= 'z' || r >= 'A' && r <= 'Z' || r >= '0' && r <= '9')
	})
	return parts
}

// singularExceptions maps lowercased table names to their Go struct names,
// overriding the mechanical rules.
var singularExceptions = map[string]string{
	"statuses": "Status",
	"series":   "Series",
	"people":   "Person",
}

// singularize applies the CONTRACTS rules to a Pascal-cased table name:
// trim trailing "s"/"es", "ies"->"y", exceptions map first.
func singularize(name string) string {
	if ex, ok := singularExceptions[strings.ToLower(name)]; ok {
		return ex
	}
	lower := strings.ToLower(name)
	switch {
	case strings.HasSuffix(lower, "ies") && len(lower) > 3:
		return name[:len(name)-3] + "y"
	case strings.HasSuffix(lower, "ses") || strings.HasSuffix(lower, "xes") ||
		strings.HasSuffix(lower, "zes") || strings.HasSuffix(lower, "ches") ||
		strings.HasSuffix(lower, "shes"):
		return name[:len(name)-2]
	case strings.HasSuffix(lower, "s") && !strings.HasSuffix(lower, "ss") && !strings.HasSuffix(lower, "us"):
		return name[:len(name)-1]
	default:
		return name
	}
}
